if (!bb.isInside(p)) return false;

int insideCount = 0;
std::mt19937 gen(std::random_device{}());
std::uniform_real_distribution<double> dist(-1.0, 1.0);

for (int i = 0; i < numberOfChecks; ++i) {
    double dx = dist(gen);
    double dy = dist(gen);
    double dz = dist(gen);

    Point3d dir(dx, dy, dz);
    double len = std::sqrt(dx*dx + dy*dy + dz*dz);
    if (len < 1e-10) {
        i--;
        continue;
    }

    Point3d farPoint(
        p.x() + dx * 1000.0,
        p.y() + dy * 1000.0,
        p.z() + dz * 1000.0
    );

    int intersections = numberIntersectedPrimitives(p, farPoint);
    if (intersections % 2 == 1) {
        insideCount++;
    }
}

return insideCount > numberOfChecks / 2;

